from pathlib import Path
import re,base64
R=Path(__file__).resolve().parents[1];(R/'lab').mkdir(exist_ok=True)
code='\n'.join(re.sub(r'^import\s+.*?;\s*$','',p.read_text(),flags=re.M).replace('export ','') for p in [R/'runtime/core.mjs',R/'runtime/canvas.mjs'])
font=base64.b64encode((R/'assets/fonts/IBMPlexSansArabic-SemiBold.ttf').read_bytes()).decode()
html='''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>@font-face{font-family:Plex;src:url(data:font/ttf;base64,__FONT__);font-weight:600}body{font-family:Plex,sans-serif;background:#f3f5f8;color:#172338;max-width:1000px;margin:auto;padding:24px}input,select{font:inherit;padding:8px;margin:6px}canvas{width:100%;height:auto;background:#fff}pre{direction:ltr;text-align:left;white-space:pre-wrap}</style><h1>مختبر الآليات — ليس قالب فيديو</h1><p>أربع تجارب قابلة للتمرير الزمني. لا يدعي المختبر تنفيذ كل مسميات القاموس أو تشغيل After Effects.</p><select id="mode"><option value="matte">قناع عربي</option><option value="spring">نابض تحليلي</option><option value="path">مسار ومؤشر</option><option value="curve">منحنى قيمة وسرعة</option></select><input id="time" type="range" min="0" max="4" step=".01" value="1.2"><div>Bezier: <input id="x1" type="number" min="0" max="1" step=".05" value=".2"><input id="y1" type="number" step=".05" value=".05"><input id="x2" type="number" min="0" max="1" step=".05" value=".2"><input id="y2" type="number" step=".05" value="1"></div><canvas id="lab" width="900" height="500"></canvas><pre id="result"></pre><script>__CORE__
const cn=document.getElementById('lab'),g=cn.getContext('2d'),el=id=>document.getElementById(id);let shaped,mask;
function draw(t){g.clearRect(0,0,900,500);let note='';const mode=el('mode').value;if(mode==='matte'){const im=rtlMatte(shaped,smooth(t/2),{target:mask,bands:3,slant:35});g.drawImage(im,450-im.width/2,240-im.height/2);note='Full shaped Arabic + independent alpha matte.';}else if(mode==='spring'){const x=120+650*spring(t-.3,springPresets.playful);g.fillStyle='#1761d5';g.beginPath();g.arc(x,245,42,0,Math.PI*2);g.fill();note='Analytical spring, sampled directly at t.';}else if(mode==='path'){const path=pathMetrics(cubicPath([80,370],[240,10],[650,500],[820,110]));strokePath(g,path,smooth(t/3),{color:'#1761d5',width:8,head:true});note=JSON.stringify(pathPoint(path,smooth(t/3)));}else{const e=cubicBezier(+el('x1').value,+el('y1').value,+el('x2').value,+el('y2').value);for(let k=0;k<2;k++){g.beginPath();for(let i=0;i<=200;i++){const u=i/200,x=70+760*u,y=k?460-80*derivative(e,u):230-170*e(u);if(i)g.lineTo(x,y);else g.moveTo(x,y);}g.strokeStyle=k?'#172338':'#1761d5';g.lineWidth=3;g.stroke();}note='Blue: value. Dark: actual numerical derivative.';}el('result').textContent='t='+t.toFixed(2)+' s\\n'+note;return cn.toDataURL('image/png');}
window.labSeek=draw;window.labReady=document.fonts.load('600 125px Plex','النص متصل').then(()=>{shaped=textSprite('النص متصل',{size:125,family:'Plex',color:'#172338'});mask=surface(shaped.width,shaped.height);draw(1.2);return true;});document.querySelectorAll('input,select').forEach(x=>x.addEventListener('input',()=>draw(+el('time').value)));
</script></html>'''
(R/'lab/index.html').write_text(html.replace('__FONT__',font).replace('__CORE__',code));print('LAB_BUILT: self-contained, four actual mechanisms, no automatic playback loop.')
